import 'dart:async';
import 'dart:developer' as developer;

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/services.dart';

import '../domain/monsters/monster_phrases.dart';
import 'latest_only_queue.dart';
import 'monster_voice.dart';

/// Where the live recordings of the game's phrases go, one `.wav` per
/// [VoiceClip] — written by `tool/record_voiceover.dart monsters`.
const monsterRecordedVoiceDir = 'assets/audio/monsters';

/// Stand-in computer-voice versions of the same phrases, generated by
/// `tool/generate_monster_tts.dart`. Used until a phrase has a live recording.
const monsterSynthVoiceDir = 'assets/audio/monsters_tts';

/// The asset files to play for [line], given every asset the app ships
/// ([bundled]), or an empty list if some part of the line has no audio at
/// all.
///
/// A line is said in the live voice only when *all* its clips have been
/// recorded; otherwise the whole line stays in the computer voice, so one
/// sentence never switches speaker halfway through.
List<String> monsterVoiceAssets(MonsterLine line, Set<String> bundled) {
  final recorded = [for (final clip in line.clips) '$monsterRecordedVoiceDir/${clip.id}.wav'];
  if (recorded.every(bundled.contains)) return recorded;
  final synthesized = [for (final clip in line.clips) '$monsterSynthVoiceDir/${clip.id}.m4a'];
  if (synthesized.every(bundled.contains)) return synthesized;
  return const [];
}

/// Plays the game's phrases and sound effects through `audioplayers`.
/// Like `AudioPlayerService`, it logs and swallows playback errors: sound
/// must never stop the game.
class MonsterVoicePlayer implements MonsterVoice {
  MonsterVoicePlayer({AssetBundle? bundle, AudioPlayer Function() playerFactory = AudioPlayer.new})
      : _playerFactory = playerFactory,
        _bundled = _listAssets(bundle ?? rootBundle);

  final AudioPlayer Function() _playerFactory;
  final Future<Set<String>> _bundled;
  final Map<MonsterSfx, AudioPlayer> _sfxPlayers = {};
  _Speaker? _speaker;
  bool _disposed = false;

  static Future<Set<String>> _listAssets(AssetBundle bundle) async {
    try {
      final manifest = await AssetManifest.loadFromAssetBundle(bundle);
      return manifest.listAssets().toSet();
    } catch (error, stackTrace) {
      developer.log('Asset list unavailable', name: 'MonsterVoicePlayer', error: error, stackTrace: stackTrace);
      return const {};
    }
  }

  // A line is never cut off by the next one: it is said to its end, and
  // then comes the latest line asked for meanwhile (see [LatestOnlyQueue]).
  late final LatestOnlyQueue<MonsterLine> _lines = LatestOnlyQueue(_speak);

  @override
  Future<void> say(MonsterLine line) => _disposed ? Future<void>.value() : _lines.add(line);

  Future<void> _speak(MonsterLine line) async {
    if (_disposed) return;
    // Each line gets a player of its own, so a line stopped by [stop] can
    // never be mistaken for a later one having finished.
    final speaker = _Speaker(_playerFactory());
    _speaker = speaker;
    try {
      for (final asset in monsterVoiceAssets(line, await _bundled)) {
        if (speaker.cancelled) break;
        await speaker.playToEnd(AssetSource(_withoutAssetsPrefix(asset)));
      }
    } catch (error, stackTrace) {
      developer.log('Voice playback failed', name: 'MonsterVoicePlayer', error: error, stackTrace: stackTrace);
    } finally {
      if (identical(_speaker, speaker)) _speaker = null;
      speaker.dispose();
    }
  }

  @override
  void playSfx(MonsterSfx sfx) {
    if (_disposed) return;
    final player = _sfxPlayers.putIfAbsent(sfx, _playerFactory);
    unawaited(_quietly(player.play(AssetSource('audio/system/${sfx.fileName}.wav'))));
  }

  @override
  void stop() {
    _lines.clear();
    _speaker?.cancel();
    _speaker = null;
  }

  @override
  void dispose() {
    stop();
    _disposed = true;
    for (final player in _sfxPlayers.values) {
      unawaited(_quietly(player.dispose()));
    }
    _sfxPlayers.clear();
  }

  // `AssetSource` adds the leading "assets/" itself.
  static String _withoutAssetsPrefix(String asset) => asset.substring('assets/'.length);
}

Future<void> _quietly(Future<void> action) => action.catchError(
      (Object error, StackTrace stackTrace) =>
          developer.log('Audio call failed', name: 'MonsterVoicePlayer', error: error, stackTrace: stackTrace),
    );

/// One line being said: a player plus the means to cut it short.
class _Speaker {
  _Speaker(this._player);

  final AudioPlayer _player;
  final Completer<void> _cancelled = Completer<void>();

  // Same bounds as AudioPlayerService: a native player that never reports a
  // start or an end must not leave the game waiting forever.
  static const _startLimit = Duration(seconds: 3);
  static const _endSlack = Duration(seconds: 2);
  static const _unknownClipLength = Duration(seconds: 6);

  bool get cancelled => _cancelled.isCompleted;

  void cancel() {
    if (cancelled) return;
    _cancelled.complete();
    unawaited(_quietly(_player.stop()));
  }

  Future<void> playToEnd(Source source) async {
    final completed = _player.onPlayerComplete.first..ignore();
    await _player.play(source).timeout(_startLimit);
    if (cancelled) return;
    Duration? length;
    try {
      length = await _player.getDuration().timeout(const Duration(seconds: 1));
    } catch (_) {
      length = null;
    }
    await Future.any([completed, _cancelled.future]).timeout((length ?? _unknownClipLength) + _endSlack);
  }

  void dispose() => unawaited(_quietly(_player.dispose()));
}
